{
  "name": "树莓派相机模块",
  "name_en": "Raspberry Pi Camera Module",
  "manufacturer": "Raspberry Pi",
  "description": "一款用于树莓派平台的小型数字相机模块，可进行实时视频采集和静态图像获取。适合实验室中的显微成像、样品观察、装置监视和基础视觉记录等场景。",
  "description_en": "A compact digital camera module for the Raspberry Pi platform, used for live video acquisition and still image capture. It is suitable for laboratory microscopy imaging, sample observation, instrument monitoring, and general visual documentation.",
  "tag_hints": [
    "Raspberry Pi camera",
    "live imaging",
    "microscopy imaging",
    "image capture",
    "ROI acquisition",
    "exposure control",
    "analog gain control"
  ],
  "actions": [
    {
      "action_name": "auto-start_live",
      "description": "启动相机实时采集。",
      "description_en": "Start live image acquisition on the camera."
    },
    {
      "action_name": "auto-stop_live",
      "description": "停止相机实时采集。",
      "description_en": "Stop live image acquisition on the camera."
    },
    {
      "action_name": "auto-suspend_live",
      "description": "暂停相机实时采集。",
      "description_en": "Suspend live image acquisition on the camera."
    },
    {
      "action_name": "auto-prepare_live",
      "description": "准备相机进入实时采集状态。",
      "description_en": "Prepare the camera for live acquisition."
    },
    {
      "action_name": "auto-close",
      "description": "关闭相机。",
      "description_en": "Close the camera."
    },
    {
      "action_name": "auto-set_exposure_time",
      "description": "设置相机曝光时间。",
      "description_en": "Set the camera exposure time."
    },
    {
      "action_name": "auto-set_analog_gain",
      "description": "设置相机模拟增益。",
      "description_en": "Set the camera analog gain."
    },
    {
      "action_name": "auto-set_blacklevel",
      "description": "设置相机黑电平。",
      "description_en": "Set the camera black level."
    },
    {
      "action_name": "auto-set_pixel_format",
      "description": "设置相机像素格式。",
      "description_en": "Set the camera pixel format."
    },
    {
      "action_name": "auto-getLast",
      "description": "获取最新一帧图像。",
      "description_en": "Get the most recent image frame."
    },
    {
      "action_name": "auto-getLastChunk",
      "description": "获取最新一段图像数据。",
      "description_en": "Get the most recent chunk of image data."
    },
    {
      "action_name": "auto-setROI",
      "description": "设置相机感兴趣区域。",
      "description_en": "Set the camera region of interest."
    },
    {
      "action_name": "auto-setPropertyValue",
      "description": "设置相机属性值。",
      "description_en": "Set a camera property value."
    },
    {
      "action_name": "auto-getPropertyValue",
      "description": "获取相机属性值。",
      "description_en": "Get a camera property value."
    },
    {
      "action_name": "auto-openPropertiesGUI",
      "description": "打开相机属性设置界面。",
      "description_en": "Open the camera properties configuration interface."
    }
  ]
}

